/* Cross-Sell Opportunity View — RFI Modul 2(f). */
let c360CrossSellKind='Semua';
function c360Owned(p){return [...c360Rows(p,'portfolio'),...c360Rows(p,'accounts'),...c360Rows(p,'credits')].filter(x=>!['Tutup','Ditutup','Lunas'].includes(x.status));}
function c360Evidence(p){const ctx=p.customer360?.context||{};return [
 {name:'Customer Profile',available:!!(p.occupation||ctx.segment),detail:[p.occupation,ctx.segment].filter(Boolean).join(' · ')||'Lengkapi pekerjaan dan segmen',tab:'Profil'},
 {name:'Portfolio',available:c360Owned(p).length>0,detail:c360Owned(p).length+' posisi produk / rekening / kredit tercatat',tab:'Portofolio'},
 {name:'Transaction',available:c360Rows(p,'transactions').length>0,detail:c360Rows(p,'transactions').length+' transaksi tercatat; bukan mutasi otomatis',tab:'Rekening & Transaksi'},
 {name:'Credit',available:c360Rows(p,'credits').length>0,detail:c360Rows(p,'credits').length+' fasilitas kredit tercatat',tab:'Kredit & Agunan'},
 {name:'Interaction',available:c360Timeline(p).length>0,detail:c360Timeline(p).length+' catatan interaksi dan keluhan',tab:'Interaksi & Keluhan'},
 {name:'Relationship',available:!!(ctx.note||ctx.employees||ctx.workingCapitalNeed||ctx.surplusFunds||c360Rows(p,'relationships').length),detail:ctx.note||'Catat kebutuhan, payroll, dana dan jaringan customer',tab:'Cross-sell'}
 ];}
const c360SignalsBase=c360Signals;
c360Signals=function(p){const ctx=p.customer360?.context||{};const signals=c360SignalsBase(p).map(s=>{const reasons=[s.reason],evidence=[];let known=false;
 if(s.kind==='Kredit'&&Number(ctx.workingCapitalNeed)>0){known=true;evidence.push('Konteks relationship: kebutuhan modal kerja '+rup(ctx.workingCapitalNeed));}
 if(s.kind==='Dana'&&Number(ctx.surplusFunds)>0){known=true;evidence.push('Konteks relationship: dana belum digunakan '+rup(ctx.surplusFunds));if(!/deposito/i.test(s.product))reasons.push('Terdapat dana belum digunakan '+rup(ctx.surplusFunds)+'. Konfirmasi kebutuhan rekening dan penempatan dana.');}
 const facilities=c360Rows(p,'credits').filter(c=>c.maturity&&c.maturity>=today()&&Date.parse(c.maturity)-Date.parse(today())<=30*86400000);if(s.kind==='Kredit'&&facilities.length)evidence.push(facilities.length+' fasilitas tercatat jatuh tempo dalam 30 hari; konfirmasi kebutuhan pembiayaan berikutnya.');
 const tx=c360Rows(p,'transactions'),inflow=tx.filter(t=>t.direction==='Masuk').reduce((n,t)=>n+Number(t.amount||0),0);if(inflow>0)evidence.push('Total arus masuk pada '+tx.length+' transaksi tercatat: '+rup(inflow)+'; cakupan tanggal mengikuti data yang tersedia.');
 const interaction=c360Timeline(p).find(x=>[x.result,x.note,x.followUp].join(' ').toLowerCase().includes(s.product.toLowerCase()));if(interaction){known=true;evidence.push('Interaksi '+(interaction.date||'tanpa tanggal')+': '+(interaction.result||interaction.note||'Produk dibahas'));}
 if(ctx.segment||p.occupation)evidence.push('Profil: '+[ctx.segment,p.occupation].filter(Boolean).join(' · '));
 if(c360Rows(p,'relationships').length)evidence.push(c360Rows(p,'relationships').length+' hubungan customer tercatat; validasi potensi referral dengan AO.');
 return {...s,reason:reasons.join(' '),evidence,status:s.existing?'Opportunity aktif':known?'Ada indikasi kebutuhan':'Perlu konfirmasi',known};});
 const payrollKnown=Number(ctx.employees)>0&&['Bank lain','BPD Bali'].includes(ctx.payrollBank);if(payrollKnown&&ctx.payrollBank==='Bank lain'){const products=activeMaster('products'),product=products.find(x=>/payroll/i.test(x.name))?.name||'';signals.unshift({product,kind:'Payroll',title:'Payroll karyawan',reason:ctx.employees+' karyawan dengan payroll melalui bank lain. Konfirmasi pengalihan payroll dan kebutuhan rekening karyawan.',evidence:['Relationship: '+ctx.employees+' karyawan','Payroll saat ini: '+ctx.payrollBank,'Estimasi payroll bulanan: '+c360Number(ctx.payroll)],known:true,status:'Ada indikasi kebutuhan',existing:db.opps.find(o=>o.profile===p.id&&mine(o)&&o.outcome==='Aktif'&&(product?o.product===product:/cross-sell payroll/i.test(o.name||'')))});}
 return signals;};
function c360SignalKey(s){return s.kind+'|'+s.product;}
function c360SignalButton(p,s){return btn(s.existing?'Buka Opportunity cross-sell':'Tinjau & buat Opportunity',"c360ReviewCrossSell('"+p.id+"',"+E(JSON.stringify(c360SignalKey(s)))+")",true);}
function c360ReviewCrossSell(id,key){const p=c360Customer(id),s=p&&c360Signals(p).find(x=>c360SignalKey(x)===key);if(!s)return toast('Peluang tidak tersedia.');if(s.existing)return go('Opportunity detail',s.existing.id);
 const choices=activeMaster('products').map(x=>x.name);if(!choices.length)return toast('Tambahkan produk aktif di Pengaturan sebelum membuat Opportunity.');
 modal('Buat Opportunity dari Cross-sell',c360Facts([['Customer',p.name],['Jenis peluang',s.kind],['Status indikasi',s.status]])+'<p>'+E(s.reason)+'</p>'+c360Choice('Produk yang ditawarkan','product',choices,s.product,true)+area('Kebutuhan yang sudah dikonfirmasi / perlu digali','crossSellNeed',s.reason,true)+'<label class="c360-confirm"><input type="checkbox" name="reviewed" required> Saya sudah meninjau data dan memilih produk yang sesuai untuk ditindaklanjuti.</label><p class="hint">Lanjutkan untuk melengkapi nilai indikatif, target closing dan AO di form Opportunity. Ini belum merupakan persetujuan atau pencairan kredit.</p>',f=>{if(!f.reviewed)throw Error('Tinjau data customer terlebih dahulu.');if(!activeMaster('products').some(x=>x.name===f.product))throw Error('Produk tidak aktif.');setTimeout(()=>c360LaunchCrossSell(id,f.product,s.kind,f.crossSellNeed),0);});
}
function c360LaunchCrossSell(id,product,kind,need){const p=c360Customer(id);if(!p)return;const existing=db.opps.find(o=>o.profile===id&&mine(o)&&o.product===product&&o.outcome==='Aktif');if(existing)return go('Opportunity detail',existing.id);newOpp(id);const form=document.querySelector('#form');if(!form)return;const set=(name,value)=>{const el=form.querySelector('[name="'+name+'"]');if(el)el.value=value};set('product',product);set('name','Cross-sell '+kind+' · '+product+' — '+p.name);set('need','Sumber: Customer 360 / Cross-Sell Opportunity View\nJenis: '+kind+'\n'+need);set('type','Expansion');const hint=document.createElement('p');hint.className='c360-opportunity-source';hint.textContent='CROSS-SELL → OPPORTUNITY · '+p.name;form.prepend(hint);}
c360CreateOpportunity=function(id,product){const p=c360Customer(id),s=p&&c360Signals(p).find(x=>x.product===product);if(s)c360ReviewCrossSell(id,c360SignalKey(s));};
function c360CrossSellSummary(p){const s=c360Signals(p),held=[...new Set(c360Owned(p).map(x=>x.product).filter(Boolean))];return '<section class="c360-crosssell-highlight"><div><small>CROSS-SELL OPPORTUNITY VIEW</small><h2>Temukan peluang produk tambahan</h2><p>Customer sudah memiliki '+E(held.length?held.join(', '):'produk yang belum lengkap tercatat')+'. Tinjau '+s.length+' potensi payroll, kredit dan dana, lalu buat Opportunity.</p></div>'+btn('Lihat Cross-sell ('+s.length+')',"c360ChangeTab('Cross-sell')",true)+'</section>';}
c360Intelligence=function(p){const ctx=p.customer360?.context||{},all=c360Signals(p),signals=all.filter(s=>c360CrossSellKind==='Semua'||s.kind===c360CrossSellKind),held=[...new Set(c360Owned(p).map(x=>x.product).filter(Boolean))];
 const steps='<ol class="c360-crosssell-steps"><li><strong>1. Cek data customer</strong><span>Periksa produk dimiliki, rekening, kredit dan riwayat interaksi.</span></li><li><strong>2. Tinjau peluang cross-sell</strong><span>Pilih Payroll, Kredit atau Dana. Baca alasan dan data pendukung.</span></li><li><strong>3. Buat Opportunity</strong><span>Konfirmasi kebutuhan, pilih produk, lalu lengkapi form Opportunity untuk masuk pipeline.</span></li></ol>';
 const cards=signals.map(s=>'<article class="c360-card c360-crosssell-card"><div class="recordtop">'+badge(s.kind)+badge(s.status)+'</div><h3>'+E(s.title||s.product)+'</h3><p>'+E(s.reason)+'</p><details><summary>Lihat alasan & data pendukung</summary><ul>'+(['Produk ini belum tercatat pada posisi produk aktif customer.',...s.evidence].map(x=>'<li>'+E(x)+'</li>').join(''))+'</ul></details><p class="hint">'+(s.known?'Indikasi dari data tercatat; AO tetap memvalidasi kebutuhan.':'Gap produk adalah bahan diskusi, belum berarti customer membutuhkan produk ini.')+'</p><div class="actions">'+c360SignalButton(p,s)+btn('Buat Task follow-up',"c360Task('"+p.id+"','Follow-up cross-sell "+s.kind+"')")+'</div></article>').join('');
 const buckets=['Payroll','Kredit','Dana'].map(kind=>{const matches=all.filter(s=>s.kind===kind);const note=kind==='Payroll'?(ctx.payrollBank==='BPD Bali'?'Payroll BPD Bali sudah tercatat.':matches.length?'Ada indikasi payroll dari data karyawan dan bank saat ini.':'Lengkapi jumlah karyawan dan bank payroll untuk mengidentifikasi peluang.'):(matches.length?matches.length+' gap produk untuk ditinjau.':'Tidak ada gap terhadap produk aktif yang tercatat.');return '<article class="c360-card"><h3>'+kind+' Opportunity</h3><p>'+E(note)+'</p>'+btn(matches.length?'Lihat peluang '+kind:'Lengkapi data kebutuhan',matches.length?"c360CrossSellKind='"+kind+"';renderContent()":"c360ContextEdit('"+p.id+"')")+'</article>';}).join('');
 return c360Section('Cross-sell Opportunity View','<p>Produk apa yang bisa ditawarkan berikutnya kepada <strong>'+E(p.name)+'</strong>? Gunakan profil dan hubungan customer untuk mengidentifikasi peluang pengembangan bisnis.</p>'+steps,btn('Lengkapi data kebutuhan',"c360ContextEdit('"+p.id+"')"))+c360Section('Produk yang dimiliki','<div class="c360-owned-products">'+held.map(x=>'<span>✓ '+E(x)+'</span>').join('')+'</div>'+(held.length?'<p class="hint">Dikonsolidasikan dari Portfolio, rekening dan fasilitas kredit aktif yang tercatat.</p>':empty('Belum ada produk tercatat. Lengkapi data sebelum menyimpulkan customer belum memiliki produk.'))+btn('Periksa portofolio',"c360ChangeTab('Portofolio')"))+c360Section('Payroll, Kredit & Dana Opportunity','<div class="c360-cardgrid">'+buckets+'</div>')+c360Section('Daftar peluang Cross-sell','<div class="c360-crosssell-filters">'+['Semua','Payroll','Kredit','Dana'].map(k=>'<button class="'+(k===c360CrossSellKind?'active':'')+'" onclick="c360CrossSellKind=\''+k+'\';renderContent()">'+k+' ('+(k==='Semua'?all.length:all.filter(s=>s.kind===k).length)+')</button>').join('')+'</div><div class="c360-cardgrid">'+cards+'</div>'+(signals.length?'':empty('Belum ada peluang untuk kategori ini. Periksa produk dimiliki dan lengkapi data kebutuhan.'))+'<p class="hint">Rekomendasi berbasis aturan CRM, belum AI scoring. Produk belum tercatat bukan bukti produk belum dimiliki. Data Core Banking dan channel Bank belum terhubung.</p>')+c360Section('Data pembentuk Relationship Intelligence','<p>Enam sumber data pada modul Customer 360 digunakan sebagai konteks saat meninjau peluang.</p><div class="c360-cardgrid">'+c360Evidence(p).map(e=>'<article class="c360-card"><small>'+E(e.available?'Ada data tercatat':'Perlu dilengkapi')+'</small><h3>'+e.name+'</h3><p>'+E(e.detail)+'</p>'+btn('Periksa data',e.name==='Relationship'?"c360ContextEdit('"+p.id+"')":"c360ChangeTab('"+e.tab+"')")+'</article>').join('')+'</div>')+c360Section('Relationship & Referral',c360Facts([['Segmen',ctx.segment||'Belum tersedia'],['Jumlah karyawan',ctx.employees??'Belum tersedia'],['Bank payroll',ctx.payrollBank||'Belum diketahui'],['Potensi payroll / bulan',c360Number(ctx.payroll)],['Kebutuhan modal kerja',c360Number(ctx.workingCapitalNeed)],['Dana belum digunakan',c360Number(ctx.surplusFunds)]])+c360Rows(p,'relationships').map(r=>'<article class="c360-card"><h3>'+E(profile(r.customerId)?.name||'Customer di luar scope')+'</h3><p>'+E(r.type)+' · '+E(r.note||'')+'</p>'+(c360Customer(r.customerId)?btn('Buka Customer 360',"go('Nasabah detail','"+r.customerId+"')"):'')+c360RowActions(p,'relationships',r)+'</article>').join(''),btn('Tambah hubungan customer',"c360Edit('"+p.id+"','relationships')"));};
const c360OverviewBeforeCrossSell=c360Overview;
c360Overview=function(p){return c360CrossSellSummary(p)+c360OverviewBeforeCrossSell(p);};
const c360CrossSellDetailBefore=c360Detail;
c360Detail=function(p){if(c360Focus!==p.id)c360CrossSellKind='Semua';let html=c360CrossSellDetailBefore(p);const guidance={'Profil':['Customer Profile','Periksa CIF, NIK, alamat, pekerjaan, AO/RM serta sumber konversi Lead. Koreksi identitas mengikuti persetujuan.'],'Portofolio':['Portfolio','Lihat produk dimiliki, plafon, baki debet, jenis kredit, kolektibilitas dan jatuh tempo. Lengkapi posisi manual jika sumber Bank belum terhubung.'],'Rekening & Transaksi':['Transaction & Account View','Periksa saldo dan status rekening aktif, dormant atau tutup. Gunakan filter tanggal untuk melihat transaksi yang tercatat.'],'Kredit & Agunan':['Collateral & Credit Information','Lihat fasilitas, taksasi dan lokasi agunan, histori pengajuan serta dokumen terkait. Foto agunan dan usaha dapat diunggah melalui Dokumen.'],'Interaksi & Keluhan':['Interaction & Complaint History','Catat tanggal, channel, hasil dan follow-up. Timeline menggabungkan aktivitas CRM dan keluhan; buat Task untuk tindak lanjut.']};const g=guidance[c360Tab];if(g)html=html.replace('</nav>','</nav><div class="c360-feature-guide"><strong>'+g[0]+'</strong><p>'+g[1]+'</p></div>');return html;};
const c360CrossSellContentBefore=renderContent;
renderContent=function(){c360CrossSellContentBefore();if(view==='Nasabah'){const app=document.querySelector('#app');if(app&&!app.querySelector('.c360-list-guide'))app.insertAdjacentHTML('afterbegin','<section class="c360-list-guide"><small>CUSTOMER 360 & RELATIONSHIP INTELLIGENCE</small><h2>Kenali customer, temukan peluang Cross-sell</h2><p>Klik nama atau baris customer untuk melihat profil, produk dimiliki, rekening, kredit, interaksi dan <strong>Cross-sell</strong>. Di detail customer, klik tombol <strong>Cross-sell</strong> untuk menawarkan produk tambahan dan membuat Opportunity.</p></section>');}};
if(typeof authUser!=='undefined'&&authUser)renderContent();

