const crossSellJourneyPlanBefore=journeyPlan;
journeyPlan=function(scenario){if(scenario!=='flow-crosssell')return crossSellJourneyPlanBefore(scenario);
 const ao=owners[0]||'Dimas',ts=()=>journey?.started||now(),day=()=>ts().slice(0,10),P=()=>profile('SIM-P');
 const step=(title,note,route,c360Tab,apply=()=>{},preview='')=>({title,note,route,c360Tab,role:ao,tab:'Overview',apply,preview});
 return [
 step('Buka Customer 360','Latihan cross-sell menggunakan customer existing. Data contoh terpisah dari data kerja.','Nasabah detail','Overview',()=>{db.profiles.push({id:'SIM-P',name:'Budi Santoso · Latihan Cross-sell',contact:'Budi',phone:'080000000000',address:'Denpasar · alamat contoh',businessAddress:'Toko contoh, Denpasar',occupation:'Pemilik toko',owner:ao,relation:'Customer',cif:'LATIHAN-CIF-CROSSSELL',dataSource:'Data latihan',customer360:{portfolio:[{id:'SIM-PF',product:'Tabungan',category:'Tabungan',balance:80000000,asOf:day(),source:'Data latihan'}],accounts:[{id:'SIM-ACC',product:'Tabungan',number:'LATIHAN-REKENING',category:'Tabungan',status:'Aktif',balance:80000000,asOf:day(),source:'Data latihan'}],transactions:[{id:'SIM-TX',accountId:'SIM-ACC',date:day(),direction:'Masuk',amount:25000000,channel:'Transfer',description:'Penerimaan usaha · contoh latihan',source:'Data latihan'}],context:{customerType:'Badan usaha',segment:'UMKM',employees:12,payrollBank:'Bank lain',payroll:48000000,workingCapitalNeed:300000000,surplusFunds:50000000,note:'Butuh modal kerja untuk menambah stok toko. Payroll dan penempatan dana dapat digali berikutnya.',actor:ao,updatedAt:ts()}}});db.activities.push({id:'SIM-DISCOVERY',profile:'SIM-P',owner:ao,type:'Telepon',result:'Tertarik KUR',note:'Customer mengonfirmasi kebutuhan tambahan stok Rp300 juta. Contoh latihan, bukan keputusan kredit.',occurred:ts(),recorded:ts()});}),
 step('Periksa produk yang dimiliki','Tabungan sudah tercatat. Periksa tanggal posisi dan data rekening sebelum menyimpulkan gap produk.','Nasabah detail','Portofolio'),
 step('Buka Cross-sell','Klik Cross-sell. Tersedia kategori Payroll, Kredit dan Dana beserta alasan dan data pendukung.','Nasabah detail','Cross-sell',()=>{c360CrossSellKind='Semua'}),
 step('Tinjau peluang Kredit','KUR belum tercatat. Kebutuhan modal kerja Rp300 juta dan hasil telepon menjadi bahan konfirmasi AO, bukan persetujuan kredit.','Nasabah detail','Cross-sell',()=>{c360CrossSellKind='Kredit'}),
 step('Konfirmasi kebutuhan dan produk','Pada penggunaan nyata, klik Tinjau & buat Opportunity, pilih produk dan konfirmasi kebutuhan. Di latihan, form hanya pratinjau.','Nasabah detail','Cross-sell',()=>{},'<section class="panel simulationform"><span class="tag">FORM · SIMULASI CROSS-SELL</span><h2>Tinjau & buat Opportunity</h2><form inert>'+field('Customer','customer','Budi Santoso · Latihan Cross-sell')+field('Produk','product','KUR')+area('Kebutuhan yang dikonfirmasi','need','Tambahan modal kerja Rp300 juta untuk stok toko. Sumber: hasil telepon dan konteks relationship.')+'<p>✓ AO sudah meninjau data customer dan kesesuaian tindak lanjut.</p><button type="button" disabled>Lanjut ke form Opportunity</button></form></section>'),
 step('Lengkapi form Opportunity','Identitas, jenis Expansion dan asal Cross-sell otomatis terbawa. AO melengkapi nominal, target closing dan penanggung jawab.','Nasabah detail','Cross-sell',()=>{},'<section class="panel simulationform"><span class="tag">FORM · SIMULASI CROSS-SELL</span><h2>Opportunity dari Cross-sell</h2><form inert>'+field('Nama Opportunity','name','Cross-sell Kredit · KUR — Budi Santoso')+field('Produk','product','KUR')+field('Jenis','type','Expansion')+field('Nilai indikatif (Rp)','value','300000000','number')+field('Target closing','closing',offset(14),'date')+field('AO','owner',ao)+'<button type="button" disabled>Simpan Opportunity</button></form></section>'),
 step('Opportunity masuk pipeline','Satu Opportunity KUR Rp300 juta dibuat pada tahap awal. Nilai ini indikatif, belum realisasi atau pencairan.','Opportunity detail','',()=>{const stage=stageDefs().find(s=>s.active&&s.type==='process')||{id:'stage-0',name:'Kebutuhan',sla:5};db.opps.push({id:'SIM-O',profile:'SIM-P',lead:'',owner:ao,name:'Cross-sell Kredit · KUR — Budi Santoso',product:'KUR',type:'Expansion',need:'Sumber: Customer 360 / Cross-Sell Opportunity View\nJenis: Kredit\nModal kerja Rp300 juta untuk stok toko, dikonfirmasi melalui telepon.',value:300000000,basis:'Plafon indikatif',probability:35,stage:stage.name,stageId:stage.id,slaDays:stage.sla,entered:ts(),created:day(),closing:offset(14),outcome:'Aktif'});}),
 step('Buat Task follow-up','Task terhubung ke customer dan Opportunity KUR yang sama agar tindak lanjut dapat dipantau.','Aktivitas detail','',()=>{db.tasks.push({id:'SIM-FOLLOW',profile:'SIM-P',opp:'SIM-O',lead:'',owner:ao,type:activeMaster('activities').find(a=>a.behavior==='call')?.name||'Telepon',purpose:'Follow-up cross-sell KUR: konfirmasi dokumen dan kebutuhan modal kerja',scheduled:day()+'T10:00',due:day()+'T17:00',status:'Terjadwal'});}),
 step('Lihat hasil di Customer 360','Task dan Opportunity muncul pada customer yang sama. Data customer dan produk existing tetap dipertahankan.','Nasabah detail','Task & Opportunity'),
 step('Cross-sell berikutnya membuka Opportunity aktif','Pada kategori Kredit, KUR kini ditandai Opportunity aktif. Klik Buka Opportunity cross-sell untuk melanjutkan record yang sama, tanpa membuat duplikat.','Nasabah detail','Cross-sell',()=>{c360CrossSellKind='Kredit'})
 ];};
